import 'dart:convert';

import 'package:flutter/services.dart';

/// Tiny valid JPEG used only if demo assets are missing.
const demoJpegFallbackBase64 =
    '';

Future<String> loadDemoJpegBase64(String stem) async {
  try {
    final wrapped = await rootBundle.loadString('assets/demo/$stem.b64');
    final cleaned = wrapped.replaceAll(RegExp(r'\s+'), '');
    if (cleaned.length > 200) return cleaned;
  } catch (_) {}
  try {
    final data = await rootBundle.load('assets/demo/$stem.jpg');
    return base64Encode(data.buffer.asUint8List());
  } catch (_) {}
  return demoJpegFallbackBase64;
}

const demoJpegDisplayBase64 = demoJpegFallbackBase64;
const demoJpegExtinguisherBase64 = demoJpegFallbackBase64;
